{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Vismodegib, a heteroaromatic drug with moderate ionization and low TPSA, had an absolute oral bioavailability of 31.8% in healthy subjects, supporting F ≥ 20% for a similarly sized heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Pethidine, a basic phenylpiperidine opioid, showed absolute oral bioavailability of 0.61 in healthy volunteers, demonstrating that a basic amine/aromatic structure can achieve high F despite ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Disopyramide, which shares the 2-pyridyl/phenyl/basic-amine motif with the query, had absolute oral bioavailability of 90%, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Methadone, a lipophilic basic drug, had an absolute oral bioavailability of 0.70 ± 0.09 in subjects, supporting high F for a similar lipophilic basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, a basic antiarrhythmic with extensive first-pass metabolism, still had an absolute oral bioavailability of 32 ± 7%, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic basic amine with a 2-pyridyl/phenyl carbinol motif. High-transfer experimental analogues—vismodegib, pethidine, encainide, disopyramide, and methadone—all show absolute oral bioavailability ≥20% (mostly 30–90%), including disopyramide with the closest pyridyl/phenyl/basic-amine framework. Low-F analogues have very low transfer scores and dissimilar scaffolds. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Unknown transporter/efflux liability (e.g., P-gp) and first-pass metabolism for the query.",
    "No experimental permeability data; the physicochemical prior is mixed due to full ionization at pH 7.4."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

